Hello, <div><br></div><div>I am hoping to code a truncated likelihood. In the users manual, you state 

x ~ dnorm(0, sd = 10) T(0, a) gives the normal probability density divided by its intergral from 0 to a. However, I am interested in coding a truncated distribution where the denominator is the integral of a different density. To do this, I created my own truncated Poisson distribution, but I am getting -Inf and NaN for the log probability of one of my variables and the following error when I try to compile my model:</div><div><br></div><div><span aria-label="Console Output" role="document" style="font-family:Consolas,&quot;Lucida Console&quot;,monospace,monospace;font-size:13.8667px;outline:none;border:none;word-break:break-all;margin:0px;line-height:1.1;color:rgb(0,0,0)"><span role="document" style="outline:none"><span style="color:rgb(197,6,11)">Error: Number of dimensions 1 of the return() argument does not match number 0 given in the returnType() statement.
 This occurred for: return(log(prob))
 This was part of the call:  {
  return(log(prob))
}</span></span></span><br></div><div><span aria-label="Console Output" role="document" style="font-family:Consolas,&quot;Lucida Console&quot;,monospace,monospace;font-size:13.8667px;outline:none;border:none;word-break:break-all;margin:0px;line-height:1.1;color:rgb(0,0,0)"><span role="document" style="outline:none"><span style="color:rgb(197,6,11)"><br></span></span></span></div><div>Below is my code and attached is the data I&#39;m using. Any help in troubleshooting would be much appreciated!</div><div><br></div><div>Best,</div><div>Annie</div><div><br></div><div>library(nimble)<br>library(dplyr)<br>library(readxl)<br>library(ggplot2)<br>library(basicMCMCplots)<br>set.seed(1)<br><br>dat &lt;- read_excel(&quot;ex_dat.xlsx&quot;) <br><br>k &lt;- 8.07<br>r &lt;- 4.12<br>x0 &lt;- 2012<br><br><br>#2007<br>p0 &lt;- 1-(1-1/2.3)^(k/r)<br><br>#2017<br>p1 &lt;- 1-(1-1/2.6)^(k/r)<br><br>#make bottom 0 because that is what the equation likes<br>l &lt;- p1-p0<br><br>#slope <br># s &lt;- (p1-p0)/(2016-2007)<br><br>dat &lt;- dat %&gt;%<br>  mutate(p = l/(1+exp(.5*(Year-x0)))+ p0)<br><br>#====================================================================<br># functions<br>#====================================================================<br><br>f_vec &lt;- nimbleFunction(<br>  run = function(x = double(0), <br>                 p = double(0)){<br>    <br>    k &lt;- 8.07<br>    r &lt;- 4.12<br><br>    tmp_vec &lt;- rep(NA, x)<br>    <br>    for (i in 1:x) {<br>      tmp_vec[i] &lt;- p*(pgamma(x-(i-1), k, rate = r) - pgamma(x-i, k, rate = r))<br>    }<br>    <br>    return(tmp_vec)<br>    returnType(double(1))<br>  })<br><br># truncation function<br>S_i &lt;- nimbleFunction(<br>  run = function(x = double(0)){<br>    <br>    k &lt;- 8.07<br>    r &lt;- 4.12<br>    <br>    out &lt;- 1-pgamma(x, k, rate = r)<br>    <br>    return(out)<br>    returnType(double(1))<br>  })<br><br># code penalty as prior<br>dpen &lt;- nimbleFunction(<br>  run = function(x = double(1), <br>                 theta = double(0), L = double(0),<br>                 log = integer(0, default = 0)) {<br>    returnType(double(0))<br>    logProb &lt;- -(theta/2)*sum((log(x[1:(L-2)]) - 2*log(x[2:(L-1)]) + log(x[3:L]))^2)<br>    if(log) return(logProb)<br>    else return(exp(logProb))<br>  })<br><br><br># code truncated likelihood<br>dpois_t &lt;- nimbleFunction(<br>  run = function(x = double(0), <br>                mu = double(0), i = double(0),<br>                log = integer(0, default = 0)) {<br>    returnType(double(0))<br>    <br>    prob &lt;- dpois(x, mu)/S_i(i)<br>    # logProb &lt;- log(prob)<br>    <br>    if(log) return(log(prob))<br>    else return(prob)<br>  })<br><br>#====================================================================<br># set up MCMC<br>#====================================================================<br>modelCode &lt;- nimbleCode({<br>  <br>  for (i in 1:L){<br>    #get mu <br>    mu[i] &lt;- sum(f_vec(i, p[i])*lambda[1:i])<br>    <br>    #likelihood -- this is what I&#39;d like to truncate <br>    x[i] ~ dpois_t(mu = mu[i], i=i)<br>    }<br>  <br>  #priors<br>  lambda[1:L] ~ dpen(theta = theta, L = L)<br>})<br><br><br><br>modelConsts &lt;- list(L = nrow(dat), <br>                    # I = 1:nrow(dat),<br>                    p = dat$p,  <br>                    theta = 1000)<br><br>modelData &lt;- list(x = dat$Notifications)<br><br>initsList &lt;- list(lambda = abs(rnorm(nrow(dat), mean(dat$Notifications), sd(dat$Notifications))))<br><br>model &lt;- nimbleModel(modelCode, data = modelData,  inits = initsList, constants = modelConsts)<br>model$initializeInfo()<br>model$calculate() <br><br>model$x<br>model$lambda<br>model$mu<br><br>model$logProb_lambda<br>model$logProb_x<br><br>#====================================================================<br># Compile and run model<br>#====================================================================<br><br># compile into nimble<br>Cmodel &lt;- compileNimble(model)<br></div>
